// ❌ MUTABLE (Forbidden in React/Redux)
const state = [1, 2, 3];
state.push(4);

// ✅ IMMUTABLE (Correct!)
const state = [1, 2, 3];
const newState = [...state, 4];

// ❌ MUTABLE Object
const user = { name: 'John' };
user.name = 'Jane';

// ✅ IMMUTABLE Object
const user = { name: 'John' };
const newUser = { ...user, name: 'Jane' };
